from __future__ import absolute_import

import logging

from taf.selenium.gnb.oam.coam.vdu.pages import v21B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(v21B.Diagnostic):
    """
    The class corresponding to diagnostic page on selenium_coam_vdu web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"Snapshot": SnapshotPageV22R1(driver, version)})


class SnapshotPageV22R1(v21B.SnapshotPageV21B):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'Snapshot']

    def __init__(self, driver, version):
        super(SnapshotPageV22R1, self).__init__(driver, version)
        self._view_panel = SnapshotPageViewPanelV22R1(driver, version)


class SnapshotPageViewPanelV22R1(v21B.SnapshotPageViewPanelV21B):
    def __init__(self, driver, version):
        super(SnapshotPageViewPanelV22R1, self).__init__(driver, version)
